\cos\theta(1 + e^{-6i\theta}) + \sin\theta(i - e^{-6i\theta}) &= 0.
\end{align*}
The complex root with argument $\theta$ between $90^\circ$ and $180^\circ$ satisfies $\theta$ in the second quadrant, i.e., $\cos\theta > 0$ and $\sin\theta < 0$. Thus,
\begin{align*}
\cos\theta &= \frac{\sin(6\theta)}{1 - \cos(6\theta)}, \\
\cos^2\theta + \sin^2\theta &= \frac{\sin^2(6\theta)}{(1 - \cos(6\theta))^2} + \frac{1 - \cos^2(6\theta)}{(1 - \cos(6\theta))^2} \\
&= \frac{\sin^2(6\theta) + \cos^2(6\theta)}{(1 - \cos(6\theta))^2} \\
&= \frac{1}{(1 - \cos(6\theta))^2} \\
&= \left(\frac{1 + \cos(6\theta)}{2} \right)^2.
\end{align*}
Therefore,
\begin{align*}
\cos^2\theta + \sin^2\theta = \left(\frac{1 + \cos(6\theta)}{2} \right)^2 > \cos^2 60^\circ &= \frac{1}{2},
\end{align*}
and thus,
\begin{align*}
0 < \theta < 120^\circ.
\end{align*}
However, since we require $\theta$ to be between $90^\circ$ and $180^\circ$, we must have
\begin{align*}
90^\circ < \theta < 120^\circ,
\end{align*}
and no value of $\theta$ satisfies the condition $\sin\theta < 0$. Conversely, if we let
\begin{align*}
z = e^{i(\theta + 180^\circ)},
\end{align*}
then we obtain the required root. Therefore,
\begin{align*}
\boxed{\theta + 180^\circ}
\end{align*}
is the required value of $\theta$.
```

